// README of each project, generated by scripts/readmes.mjs (HTML with %BASE% in its image paths), for the README
// card of the canvas and the project page. The browser loads each one when needed; the prerender hands all of
// them over at once (entry-server.tsx), so each project page carries its README and the client bundle none.
const lazy = import.meta.glob<string>('./readmes/*.html', { query: '?raw', import: 'default' });
let atOnce: Record<string, string> = {};

/** The prerender's READMEs (any glob of the folder: keyed here by file name, '<slug>.html'). */
export const provideReadmes = (all: Record<string, string>) => {
  atOnce = Object.fromEntries(Object.entries(all).map(([k, v]) => [k.slice(k.lastIndexOf('/') + 1), v]));
};

/** The site base in the image paths of a README. */
const withBase = (html: string) => html.replaceAll('%BASE%', import.meta.env.BASE_URL);

/** The README of a project, loaded on demand. */
export const loadReadme = (slug: string) => lazy[`./readmes/${slug}.html`]?.().then(withBase);

/** The README of a project at once: only in the prerender (null on the client). */
export const readmeNow = (slug: string) => {
  const html = atOnce[`${slug}.html`];
  return html === undefined ? null : withBase(html);
};
